// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SwarmFeed} from "src/SwarmFeed.sol";
import {SwarmRelay} from "src/SwarmRelay.sol";
import {OracleAsker} from "src/OracleAsker.sol";
import {MockIMD} from "src/MockIMD.sol";
import {IIntake} from "src/interfaces/IIntake.sol";
import {
    APPROVED_OPERATOR,
    INTAKE,
    ORACLE_ACTION,
    ATTESTATION_RELAYER,
    ASK_MIN_INTERVAL,
    ASK_TIMEOUT
} from "src/DeploymentConfig.sol";

/// @dev A concrete SwarmFeed whose attester key the test holds (same shape as test/helpers/ConfigurableSwarmFeed).
contract ProofFeed is SwarmFeed {
    constructor(address attester_, address relayer_, uint256 maxAge_, uint256 cap_)
        SwarmFeed(attester_, relayer_, 1, 3, maxAge_, cap_)
    {}

    function seed(uint256 value) external {
        _accept(value, uint64(block.timestamp));
    }
}

/// @dev The Intake as PR #66 behaves: collects the price, records the callback, completes with a 200k stipend.
contract ProofIntake {
    mapping(bytes32 => mapping(address => uint256)) public priceOf;
    mapping(bytes32 => IIntake.Callback) public callbackOf;
    uint256 public nonce;

    function setPrice(bytes32 action, address asset, uint256 amount) external {
        priceOf[action][asset] = amount;
    }

    function request(bytes32 action, bytes calldata, IIntake.Callback calldata callback, address asset, uint256 amount)
        external
        payable
        returns (bytes32 requestId)
    {
        uint256 price = priceOf[action][asset];
        require(price != 0 && amount >= price, "not sold");
        IERC20(asset).transferFrom(msg.sender, address(this), amount);
        requestId = keccak256(abi.encode(block.chainid, address(this), ++nonce));
        callbackOf[requestId] = callback;
    }

    function complete(bytes32 requestId, bytes calldata args) external returns (bool delivered) {
        IIntake.Callback memory c = callbackOf[requestId];
        (delivered,) = c.target.call{gas: 200_000}(bytes.concat(c.selector, args));
    }
}

/// @notice OracleAsker.onOracleResult decides "the Treasury paid" by `f.lastAsk == f.inFlightAt`. A refused
/// Treasury purchase writes lastAsk = now + ASK_TIMEOUT - ASK_MIN_INTERVAL, a FUTURE timestamp; an `askPaid`
/// sent in the block with exactly that timestamp writes inFlightAt equal to it, so when the Intake delivers
/// that caller-paid request and the feed refuses it (the caller hand-relayed the same bytes first) the
/// callback treats it as the Treasury's own refusal and pushes lastAsk another two hours out. Repeating
/// that every cycle holds the Treasury off indefinitely for 0.5 IMD per two hours: the state the final
/// panel audit's low was meant to close.
contract BackOffForgeryTest is Test {
    uint256 private constant ATTESTER_KEY = 0xA11CE;
    uint256 private constant PRICE = 0.5 ether;
    address private constant ATTACKER = address(0xA77);
    bytes private constant HEALTH_BODY = '{"question":"network health"}';

    MockIMD private imd;
    ProofIntake private intake;
    ProofFeed private healthFeed;
    OracleAsker private asker;

    function setUp() public {
        vm.chainId(11155111);
        vm.warp(10 days);
        vm.roll(1_000);
        vm.etch(ATTESTATION_RELAYER, address(new SwarmRelay()).code);
        vm.etch(INTAKE, address(new ProofIntake()).code);
        intake = ProofIntake(INTAKE);
        imd = new MockIMD();
        intake.setPrice(ORACLE_ACTION, address(imd), PRICE);

        healthFeed = new ProofFeed(vm.addr(ATTESTER_KEY), ATTESTATION_RELAYER, 1 days, 2000);
        address[] memory feeds = new address[](1);
        feeds[0] = address(healthFeed);
        bytes32[] memory hashes = new bytes32[](1);
        hashes[0] = keccak256(HEALTH_BODY);
        bool[] memory tracks = new bool[](1);
        bool[] memory keepAlive = new bool[](1);
        keepAlive[0] = true;
        asker = new OracleAsker(IERC20(address(imd)), feeds, hashes, tracks, keepAlive);
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(address(asker), 100 ether);
        imd.mint(ATTACKER, 10 ether);
        vm.stopPrank();
        healthFeed.seed(0.9 ether);
    }

    function test_aCallerPaidRefusalTimedToTheBackOffReadsAsTreasuryPaidAndExtendsIt() public {
        // The NHI keep-alive: 18h in, the Treasury buys. Its answer is refused (any refusal: here a bad
        // signature; a hand relay of the same bytes before the callback does the same), so the back-off lands.
        vm.warp(block.timestamp + 20 hours);
        bytes32 r1 = asker.ask(address(healthFeed), HEALTH_BODY);
        assertTrue(intake.complete(r1, abi.encode(r1, _attestation(r1, 0.9 ether), hex"00")), "refused, callback completes");
        (,,, uint64 backedOffUntil,,,) = asker.feeds(address(healthFeed));
        assertEq(backedOffUntil, uint64(block.timestamp + ASK_TIMEOUT - ASK_MIN_INTERVAL), "the Treasury's own refusal backs it off");

        // ATTACKER waits for the block whose timestamp equals that future lastAsk and buys with its own IMD.
        vm.warp(backedOffUntil);
        vm.startPrank(ATTACKER);
        imd.approve(address(asker), PRICE);
        bytes32 r2 = asker.askPaid(address(healthFeed), HEALTH_BODY, PRICE);
        vm.stopPrank();
        (,,, uint64 lastAsk,, uint64 inFlightAt,) = asker.feeds(address(healthFeed));
        assertEq(lastAsk, inFlightAt, "a caller-paid request now carries the Treasury-paid signature");

        // The answer is public before the callback; ATTACKER relays it by hand, then the Intake delivers.
        vm.warp(block.timestamp + 5 minutes);
        SwarmFeed.OracleAttestation memory a = _attestation(r2, 0.9 ether);
        bytes memory sig = _sign(a);
        vm.prank(ATTACKER);
        SwarmRelay(ATTESTATION_RELAYER).relay(healthFeed, a, sig);
        assertTrue(intake.complete(r2, abi.encode(r2, a, sig)), "refused as a replay, callback completes");

        // EXPECTED (the final panel audit fix, OracleAsker.sol:273-293): only the Treasury's own refused
        // purchase backs the Treasury off, so a caller-paid refusal leaves lastAsk where it was.
        (,,, uint64 after_,,,) = asker.feeds(address(healthFeed));
        assertEq(after_, backedOffUntil, "a caller-paid refusal must not extend the Treasury's back-off");
    }

    function _attestation(bytes32 id, uint256 figure) private view returns (SwarmFeed.OracleAttestation memory a) {
        a.requestId = id;
        a.chainId = 1;
        a.questionHash = keccak256("q");
        a.answerType = 3;
        a.answer = abi.encode(figure);
        a.figure = figure;
        a.fromBlock = 100;
        a.toBlock = 200;
        a.blockHash = keccak256("b");
        a.panelJobId = keccak256("panel");
        a.panelSize = 60;
        a.quorum = 20;
        a.agreed = 40;
        a.issuedAt = uint64(block.timestamp);
        a.expiresAt = uint64(block.timestamp + 1 hours);
    }

    function _sign(SwarmFeed.OracleAttestation memory a) private view returns (bytes memory) {
        bytes32 body = keccak256(
            bytes.concat(
                abi.encode(
                    healthFeed.ATTESTATION_TYPEHASH(), a.requestId, a.chainId, a.questionHash, a.answerType,
                    keccak256(a.answer), a.figure
                ),
                abi.encode(
                    a.fromBlock, a.toBlock, a.blockHash, a.panelJobId, a.panelSize, a.quorum, a.agreed,
                    a.issuedAt, a.expiresAt
                )
            )
        );
        (uint8 v, bytes32 r, bytes32 s) =
            vm.sign(ATTESTER_KEY, keccak256(abi.encodePacked("\x19\x01", healthFeed.DOMAIN_SEPARATOR(), body)));
        return abi.encodePacked(r, s, v);
    }
}

